<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Panda Message for Aria</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Playfair+Display:ital,wght@0,500;0,700;1,500&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #f3f4f6;
        }

        .font-serif {
            font-family: 'Playfair Display', serif;
        }

        /* 3D Envelope Styles */
        .envelope-container {
            perspective: 1000px;
            transform-style: preserve-3d;
        }

        .envelope-body {
            position: relative;
            width: 340px;
            height: 220px;
            background: #cde8ce; /* Light Sage Green */
            border-radius: 12px;
            box-shadow: 
                0 20px 40px -10px rgba(0,0,0,0.1),
                0 10px 20px -5px rgba(0,0,0,0.05),
                inset 0 -2px 5px rgba(255,255,255,0.4);
            transform-style: preserve-3d;
            transition: transform 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        .envelope-flap {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 110px; /* Half height */
            background: #b9ddb9; /* Slightly darker for depth */
            border-radius: 12px 12px 100% 100%;
            transform-origin: top center;
            transform: rotateX(0deg);
            z-index: 10;
            box-shadow: inset 0 5px 15px rgba(255,255,255,0.3);
            transition: all 0.6s ease-in-out;
            cursor: pointer;
        }

        /* The inner shadow of the flap to make it look like it's folding over */
        .envelope-flap::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 90%;
            height: 60px;
            background: linear-gradient(to bottom, transparent, rgba(0,0,0,0.03));
            border-radius: 50%;
        }

        .letter-paper {
            position: absolute;
            top: 25px;
            left: 50%;
            transform: translateX(-50%) translateY(-10px); /* Slightly hidden initially */
            width: 300px;
            height: 200px;
            background: #ffffff;
            border-radius: 4px;
            z-index: 5;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding-top: 30px;
            box-shadow: 0 4px 10px rgba(0,0,0,0.05);
            transition: transform 0.6s ease-in-out 0.2s, opacity 0.4s ease-in-out;
            opacity: 0.9;
        }

        .wax-seal {
            position: absolute;
            bottom: -18px; /* Overlap the flap edge */
            left: 50%;
            transform: translateX(-50%);
            width: 44px;
            height: 44px;
            background: #067a62; /* Deep Teal */
            border-radius: 50%;
            z-index: 20;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 
                0 4px 8px rgba(0,0,0,0.2), 
                inset 0 2px 4px rgba(255,255,255,0.3);
            border: 2px solid #055e4b;
            transition: transform 0.4s ease;
        }

        .wax-seal:hover {
            transform: translateX(-50%) scale(1.05) rotate(-5deg);
        }

        .wax-icon {
            color: white;
            font-size: 22px;
            filter: drop-shadow(0 1px 1px rgba(0,0,0,0.2));
        }

        /* Animation States */
        .open .envelope-flap {
            transform: rotateX(-180deg);
            z-index: 5; /* Move behind letter */
            background: #a8d4a8;
        }

        .open .letter-paper {
            transform: translateX(-50%) translateY(-80px); /* Pop up */
            opacity: 1;
            box-shadow: 0 20px 30px rgba(0,0,0,0.15);
        }

        .open .wax-seal {
            opacity: 0;
            pointer-events: none;
            transform: translateX(-50%) scale(0.5);
        }

        /* Panda Float */
        @keyframes float {
            0%, 100% { transform: translateY(0px) rotate(0deg); }
            50% { transform: translateY(-10px) rotate(2deg); }
        }
        .panda-float {
            animation: float 4s ease-in-out infinite;
        }
    </style>
</head>
<body class="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-hidden">

    <!-- Top Badge -->
    <div class="absolute top-6 bg-white px-5 py-2 rounded-full shadow-sm flex items-center gap-2 text-sm font-medium text-gray-600 border border-gray-100 z-10">
        <span>🐼</span> sent with Panda Messages
    </div>

    <!-- Main Card Container -->
    <main class="bg-white w-full max-w-[95%] md:max-w-4xl h-auto min-h-[85vh] rounded-[32px] shadow-xl flex flex-col items-center justify-center relative overflow-hidden mt-8 mb-8">

        <!-- Envelope Interaction Area -->
        <div id="envelope-wrapper" class="envelope-container cursor-pointer group select-none mb-10" onclick="toggleEnvelope()">

            <!-- Envelope Body (Back/Bottom part) -->
            <div class="envelope-body group-hover:-translate-y-2 transition-transform duration-300">

                <!-- Letter Inside -->
                <div class="letter-paper">
                    <!-- Decorative lines on paper -->
                    <div class="w-12 h-2 bg-teal-200 rounded-full mb-3"></div>
                    <div class="w-24 h-2 bg-gray-100 rounded-full mb-2"></div>
                    <div class="w-20 h-2 bg-gray-100 rounded-full"></div>

                    <!-- Hidden content that appears on open -->
                    <div class="mt-8 text-center opacity-0 transition-opacity duration-500 delay-300 absolute inset-0 flex flex-col items-center justify-center bg-white" id="hidden-content">
                        <p class="text-2xl font-serif text-gray-800">For Aria,</p>
                        <p class="text-sm text-gray-500 mt-2 font-light italic">A little surprise awaits...</p>
                        <button onclick="event.stopPropagation(); alert('Redirecting to gift...')" class="mt-6 bg-black text-white px-6 py-2 rounded-full text-xs uppercase tracking-widest hover:bg-gray-800 transition-colors">
                            View Gift
                        </button>
                    </div>
                </div>

                <!-- Flap -->
                <div class="envelope-flap"></div>

                <!-- Wax Seal -->
                <div class="wax-seal">
                    <span class="wax-icon">🐼</span> <!-- Using emoji as icon fallback or simple SVG -->
                </div>
            </div>
        </div>

        <!-- Text Content -->
        <div class="text-center space-y-3 px-4 pb-16">
            <h1 class="font-serif text-2xl md:text-3xl text-gray-800 tracking-wide">
                Panda has a little something for <span class="font-bold text-black">Aria</span>
            </h1>
            <p class="text-gray-400 text-sm font-light tracking-wide">
                from Leo • tap the envelope to open
            </p>
        </div>

        <!-- Floating Panda Decoration -->
        <div class="absolute bottom-24 right-[15%] md:right-[25%] panda-float pointer-events-none select-none">
             <!-- Simple CSS/SVG representation of a cute panda face to match screenshot vibe without external assets if possible, but using emoji as robust fallback per requirements -->
             <img src="https://api.dicebear.com/7.x/bottts/svg?seed=panda&backgroundColor=transparent" alt="Panda" class="w-14 h-14 grayscale opacity-80 mix-blend-multiply" style="display:none;"> <!-- Fallback hidden -->

             <!-- Using a high quality data URI or SVG for the panda face to ensure it looks premium and matches the "cute" requirement -->
             <svg width="64" height="64" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" class="drop-shadow-lg">
                 <circle cx="50" cy="55" r="35" fill="#FFF"/>
                 <circle cx="25" cy="30" r="14" fill="#333"/>
                 <circle cx="75" cy="30" r="14" fill="#333"/>
                 <ellipse cx="38" cy="52" rx="5" ry="7" fill="#333"/>
                 <ellipse cx="62" cy="52" rx="5" ry="7" fill="#333"/>
                 <ellipse cx="50" cy="62" rx="6" ry="4" fill="#333"/>
                 <path d="M45 68 Q50 73 55 68" stroke="#333" stroke-width="2" stroke-linecap="round"/>
             </svg>
        </div>

    </main>

    <!-- Bottom Left Nav -->
    <div class="fixed bottom-6 left-6 z-50">
        <button class="w-10 h-10 bg-[#222] text-white rounded-full flex items-center justify-center font-bold text-lg hover:bg-black transition-colors shadow-lg">
            N
        </button>
    </div>

    <script>
        let isOpen = false;

        function toggleEnvelope() {
            const wrapper = document.getElementById('envelope-wrapper');
            const hiddenContent = document.getElementById('hidden-content');

            isOpen = !isOpen;

            if(isOpen) {
                wrapper.classList.add('open');
                // Show content inside letter after animation starts
                setTimeout(() => {
                    hiddenContent.style.opacity = '1';
                }, 600);
            } else {
                wrapper.classList.remove('open');
                hiddenContent.style.opacity = '0';
            }
        }
    </script>
</body>
</html>
```
